-- 九黎靈貓 WEB 1.4 安全帳本完整遷移（舊RPC會被關閉，請先備份）

-- 九黎靈貓 WEB 1.4：正式測試用伺服器權威資料表
-- 避免改動 LINE 原版資料表。請使用整包 migration 在同一交易中部署。
create table if not exists public.jiuli_secure_catalog (
 kind text not null, name text not null, category text not null default '', attrs jsonb not null default '{}'::jsonb,
 primary key(kind,name)
);
create table if not exists public.jiuli_secure_shop (
 name text primary key,
 currency text not null check(currency in ('gold','yuanbao')),
 price bigint not null check(price>0),
 item_type text not null check(item_type in ('item','chest','fragments','fruit'))
);
insert into public.jiuli_secure_shop(name,currency,price,item_type) values
 ('時光加速','yuanbao',800,'item'),('自動提竿','yuanbao',1300,'item'),('稀有魚餌','yuanbao',900,'item'),
 ('全田施肥券','gold',2800,'item'),('種子補給箱','gold',1500,'item'),('料理加速券','yuanbao',900,'item'),
 ('寵物碎片','yuanbao',1200,'fragments'),('戰力果實','yuanbao',1500,'fruit'),
 ('木製寶箱','gold',2000,'chest'),('星光寶箱','yuanbao',3000,'chest'),
 ('普通寶箱','gold',150,'chest'),('精良寶箱','gold',800,'chest'),('稀有寶箱','yuanbao',30,'chest'),
 ('神秘寶箱','yuanbao',50,'chest'),('究極寶箱','yuanbao',99000,'chest'),
 ('永恆寶箱','yuanbao',5000,'chest')
on conflict (name) do update set currency=excluded.currency,price=excluded.price,item_type=excluded.item_type;
create table if not exists public.jiuli_secure_accounts (
 user_id uuid primary key references auth.users(id) on delete cascade,
 state jsonb not null,
 revision bigint not null default 1,
 migrated_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
create table if not exists public.jiuli_secure_requests (
 user_id uuid not null references auth.users(id) on delete cascade,
 request_id uuid not null,
 action text not null,
 result jsonb not null,
 created_at timestamptz not null default now(),
 primary key(user_id,request_id)
);
create index if not exists jiuli_secure_requests_date on public.jiuli_secure_requests(created_at);
create table if not exists public.jiuli_secure_bank (
 user_id uuid primary key references auth.users(id) on delete cascade,
 balance bigint not null default 0 check(balance>=0)
);
create table if not exists public.jiuli_secure_bank_pool (
 id boolean primary key default true check(id=true),
 amount bigint not null default 0 check(amount>=0)
);
insert into public.jiuli_secure_bank_pool(id,amount) values (true,0) on conflict do nothing;
create table if not exists public.jiuli_secure_jail (
 user_id uuid primary key references auth.users(id) on delete cascade,
 until_at timestamptz
);
create table if not exists public.jiuli_secure_teams (
 id uuid primary key default gen_random_uuid(),
 code text not null unique,
 leader_id uuid not null references auth.users(id) on delete cascade,
 status text not null default 'open' check(status in ('open','finished')),
 created_at timestamptz not null default now()
);
create table if not exists public.jiuli_secure_team_members (
 team_id uuid not null references public.jiuli_secure_teams(id) on delete cascade,
 user_id uuid not null references auth.users(id) on delete cascade,
 primary key(team_id,user_id)
);
create table if not exists public.jiuli_secure_bombs (
 user_id uuid primary key references auth.users(id) on delete cascade,
 answer integer not null check(answer between 1 and 100)
);
create table if not exists public.jiuli_secure_events (
 id bigint generated always as identity primary key,
 user_id uuid not null references auth.users(id) on delete cascade,
 action text not null,
 note text not null default '',
 before_gold bigint not null,
 after_gold bigint not null,
 before_yuanbao bigint not null,
 after_yuanbao bigint not null,
 at timestamptz not null default now()
);
create index if not exists jiuli_secure_events_user on public.jiuli_secure_events(user_id,id desc);

-- 凍結當下的既有雲端存檔作為升級快照（這些是舊版前端產生資料，不能追溯證明沒有作弊）。
-- 之後的所有資產操作只以 jiuli_secure_accounts 為準，從此不再允許舊版任意覆寫。
insert into public.jiuli_secure_accounts(user_id,state,revision)
select user_id,game_state,1 from public.jiuli_web_saves
where jsonb_typeof(game_state)='object'
on conflict(user_id) do nothing;

-- 如果 1.3 共同銀行已經使用，轉移舊存款與獎池，避免重設後玩家損失金幣。
do $migration$
begin
 if pg_catalog.to_regclass('public.jiuli_web_bank_accounts') is not null then
  insert into public.jiuli_secure_bank(user_id,balance)
  select user_id,balance from public.jiuli_web_bank_accounts
  where balance>=0
  on conflict(user_id) do nothing;
 end if;
 if pg_catalog.to_regclass('public.jiuli_web_bank_pool') is not null then
  update public.jiuli_secure_bank_pool set amount=old.amount
  from public.jiuli_web_bank_pool old
  where old.id=true and public.jiuli_secure_bank_pool.id=true and public.jiuli_secure_bank_pool.amount=0;
 end if;
end;
$migration$;
alter table public.jiuli_secure_shop enable row level security;
alter table public.jiuli_secure_catalog enable row level security;
alter table public.jiuli_secure_accounts enable row level security;
alter table public.jiuli_secure_requests enable row level security;
alter table public.jiuli_secure_bank enable row level security;
alter table public.jiuli_secure_bank_pool enable row level security;
alter table public.jiuli_secure_jail enable row level security;
alter table public.jiuli_secure_teams enable row level security;
alter table public.jiuli_secure_team_members enable row level security;
alter table public.jiuli_secure_bombs enable row level security;
alter table public.jiuli_secure_events enable row level security;
-- 對 anon / authenticated 的直接 DML 不授權；唯一寫入方式為具身份驗證的單入口 RPC。
revoke all on public.jiuli_secure_shop,public.jiuli_secure_catalog,public.jiuli_secure_accounts,
public.jiuli_secure_requests,public.jiuli_secure_bank,public.jiuli_secure_bank_pool,
public.jiuli_secure_jail,public.jiuli_secure_teams,public.jiuli_secure_team_members,public.jiuli_secure_bombs,public.jiuli_secure_events from public,anon,authenticated;
-- 用戶只能經 RPC 讀取自己的權威存檔，不能透過 REST 直接竄改。


