from jsonb_to_recordset('[{"kind": "crime", "name": "吃泡麵竟然沒加蛋，造成宇宙蛋黃失衡", "category": "經典罪名", "attrs": {"title": "泡麵不加蛋重刑犯"}}, {"kind": "crime", "name": "把最後一顆珍珠留給吸管，涉及珍奶情感勒索", "category": "經典罪名", "attrs": {"title": "珍奶秩序破壞者"}}, {"kind": "crime", "name": "打開冰箱三次卻不拿東西，浪費冷氣的青春", "category": "經典罪名", "attrs": {"title": "冰箱巡邏嫌疑貓"}}, {"kind": "crime", "name": "說好只滑五分鐘手機，卻把明天滑成昨天", "category": "經典罪名", "attrs": {"title": "深夜滑手機慣犯"}}, {"kind": "crime", "name": "火鍋加芋頭還大聲鼓掌，擾亂鍋底公約", "category": "經典罪名", "attrs": {"title": "火鍋芋頭首謀"}}, {"kind": "crime", "name": "凌晨肚子餓卻只喝水，讓宵夜店空虛", "category": "經典罪名", "attrs": {"title": "宵夜棄養疑犯"}}, {"kind": "crime", "name": "把雞排切成九十九塊，涉嫌故意刁難筷子", "category": "經典罪名", "attrs": {"title": "雞排切碎總指揮"}}, {"kind": "crime", "name": "對路邊的貓叫老闆，違反人貓職場倫理", "category": "經典罪名", "attrs": {"title": "喵界非法下屬"}}, {"kind": "crime", "name": "把披薩鳳梨當水果沙拉，擾亂義大利時空", "category": "經典罪名", "attrs": {"title": "鳳梨披薩教主"}}, {"kind": "crime", "name": "洗澡唱歌卻沒開售票系統，涉嫌無照巡演", "category": "經典罪名", "attrs": {"title": "浴室歌王逃票犯"}}, {"kind": "crime", "name": "一口氣按了五次貪睡鬧鐘，違反時間管理條約", "category": "經典罪名", "attrs": {"title": "鬧鐘抗命犯"}}, {"kind": "crime", "name": "拿薯條沾冰淇淋，卻拒絕申請甜鹹通行證", "category": "經典罪名", "attrs": {"title": "甜鹹跨境走私王"}}, {"kind": "crime", "name": "說出「我快到了」但還躺在床上，涉嫌地圖欺騙", "category": "經典罪名", "attrs": {"title": "棉被定位詐術師"}}, {"kind": "crime", "name": "把便當滷蛋留到最後，讓蛋擔任壓軸巨星", "category": "經典罪名", "attrs": {"title": "滷蛋延後出場犯"}}, {"kind": "crime", "name": "對空氣說借過，導致路過的風感到困惑", "category": "經典罪名", "attrs": {"title": "空氣交通違規者"}}, {"kind": "crime", "name": "睡覺不關燈，讓影子加班到天亮", "category": "經典罪名", "attrs": {"title": "影子加班主謀"}}, {"kind": "crime", "name": "拍食物拍到冷掉，涉嫌虐待熱騰騰", "category": "經典罪名", "attrs": {"title": "食物攝影拖延犯"}}, {"kind": "crime", "name": "襪子左右不同色，妨礙襪子認親程序", "category": "經典罪名", "attrs": {"title": "襪子分居調解犯"}}, {"kind": "crime", "name": "珍奶加椰果再加布丁，涉嫌組織杯中演唱會", "category": "經典罪名", "attrs": {"title": "手搖杯擴建黑手"}}, {"kind": "crime", "name": "看到電梯按鈕就想全按，造成樓層情緒不穩", "category": "經典罪名", "attrs": {"title": "電梯巡迴怪客"}}, {"kind": "crime", "name": "把早餐當宵夜、宵夜當早餐，倒轉胃的時區", "category": "經典罪名", "attrs": {"title": "食物時區偷渡客"}}, {"kind": "crime", "name": "外送備註寫「隨便」，卻認真研究菜單一小時", "category": "經典罪名", "attrs": {"title": "菜單選擇困難犯"}}, {"kind": "crime", "name": "打噴嚏太有節奏，讓隔壁桌以為在打拍子", "category": "經典罪名", "attrs": {"title": "鼻腔節奏大師"}}, {"kind": "crime", "name": "買了運動鞋卻只用來走去買炸雞", "category": "經典罪名", "attrs": {"title": "健身計畫通緝貓"}}, {"kind": "crime", "name": "在群組傳「哈哈」卻面無表情，涉嫌笑聲造假", "category": "經典罪名", "attrs": {"title": "哈哈偽造專家"}}, {"kind": "crime", "name": "對仙人掌說悄悄話，讓其他盆栽吃醋", "category": "經典罪名", "attrs": {"title": "植物八卦散播者"}}, {"kind": "crime", "name": "冷笑話太冷，讓冰箱向你申請暖氣補助", "category": "經典罪名", "attrs": {"title": "冰箱降溫主謀"}}, {"kind": "crime", "name": "打開雨傘卻忘了下雨，涉嫌氣象預支", "category": "經典罪名", "attrs": {"title": "晴天雨傘暴走王"}}, {"kind": "crime", "name": "點餐時說不餓，卻偷吃朋友三分之二的薯條", "category": "經典罪名", "attrs": {"title": "薯條消失魔術師"}}, {"kind": "crime", "name": "把星期一當成星期五慶祝，擾亂工作日秩序", "category": "經典罪名", "attrs": {"title": "週一假日冒充犯"}}, {"kind": "crime", "name": "給鬧鐘取名「再睡一下」，涉嫌煽動集體遲到", "category": "經典罪名", "attrs": {"title": "鬧鐘改名幕後黑手"}}, {"kind": "crime", "name": "吃火鍋先喝湯，讓青菜失去出場機會", "category": "經典罪名", "attrs": {"title": "火鍋開場違規者"}}]'::jsonb) as t(kind text,name text,category text,attrs jsonb)
on conflict(kind,name) do update set category=excluded.category,attrs=excluded.attrs;


-- WEB 1.4 伺服器權威遊戲引擎。所有時鐘/獎勵/價格均由 PostgreSQL 決定。
create or replace function public.jiuli_secure_int(p_state jsonb,p_key text)
returns bigint language sql immutable set search_path='' as $sql$
select case when p_state ? p_key and (p_state->>p_key) ~ '^\d{1,15}$' then (p_state->>p_key)::bigint else 0 end
$sql$;
create or replace function public.jiuli_secure_set(p_state jsonb,p_key text,p_value bigint)
returns jsonb language sql immutable set search_path='' as $sql$
select pg_catalog.jsonb_set(p_state,array[p_key],pg_catalog.to_jsonb(p_value),true)
$sql$;
create or replace function public.jiuli_secure_adjust(p_state jsonb,p_field text,p_name text,p_delta bigint)
returns jsonb language plpgsql immutable set search_path='' as $fn$
declare v_obj jsonb:=coalesce(p_state->p_field,'{}'::jsonb);v_current bigint;
begin
 if p_delta=0 then return p_state;end if;
 v_current:=public.jiuli_secure_int(v_obj,p_name);
 if v_current+p_delta<0 or v_current+p_delta>100000000 then raise exception 'INVALID_INVENTORY';end if;
 return pg_catalog.jsonb_set(p_state,array[p_field],pg_catalog.jsonb_set(v_obj,array[p_name],pg_catalog.to_jsonb(v_current+p_delta),true),true);
end;$fn$;
create or replace function public.jiuli_secure_default(p_ms bigint)
returns jsonb language sql stable set search_path='' as $sql$
 select pg_catalog.jsonb_build_object(
 'version',1,'createdAt',p_ms,'name','靈貓旅人','gold',30000,'yuanbao',50000,'level',1,'xp',0,'signIn','', 'newbieBonus',false,
 'fish','[]'::jsonb,'discovered','[]'::jsonb,'fishing',null,'speedCharges',0,'autoCharges',0,'baitCharges',0,
 'farmLevel',1,'farmXp',0,'plots','[null,null,null,null,null,null,null,null,null,null]'::jsonb,
 'seeds','{"蘿蔔":3,"白菜":3,"番茄":3,"玉米":3,"草莓":3}'::jsonb,
 'crops','{"番茄":3,"玉米":3}'::jsonb,'fertDate','','fertUsed',0,
 'kitchen','[]'::jsonb,'dishes','[]'::jsonb,'reviews',0,'restaurantSales',0
 ) || pg_catalog.jsonb_build_object(
 'pets','[]'::jsonb,'activePet','','fragments',0,'fruit',3,
 'houses','[]'::jsonb,'rentRecords','[]'::jsonb,'rentTotal',0,
 'court',null,'courtRecords','[]'::jsonb,'courtTitle','','courtLast',0,'courtDay','','courtDaily',0,
 'delivery',null,'deliveries',0,'bank',0,
 'chests','{"木製寶箱":3,"星光寶箱":1}'::jsonb,'items','{"時光加速":2,"自動提竿":1}'::jsonb,
 'dungeonDate','','dungeonRuns',0,'dungeonMax',0,
 'bomb','{"answer":0,"tries":0,"low":1,"high":100}'::jsonb,
 'stats','{"casts":0,"harvests":0,"cooked":0,"courtWins":0,"courtLosses":0,"dungeonRuns":0,"fishSold":0}'::jsonb,
 'activity','[]'::jsonb
 );
$sql$;

create or replace function public.jiuli_secure_game(p_action text,p_args jsonb default '{}'::jsonb,p_request_id uuid default null)
returns jsonb language plpgsql security definer set search_path = '' as $game$
declare
 v_uid uuid:=auth.uid();v_st jsonb;v_before jsonb;v_now bigint:=(extract(epoch from pg_catalog.clock_timestamp())*1000)::bigint;
 v_day text:=pg_catalog.to_char(pg_catalog.now() at time zone 'Asia/Taipei','YYYY-MM-DD');
 v_gold bigint;v_y bigint;v_old_gold bigint;v_old_y bigint;v_n bigint;v_i integer;v_j integer;
 v_name text:=pg_catalog.left(coalesce(p_args->>'name',''),120);v_text text:=pg_catalog.left(coalesce(p_args->>'text',''),512);
 v_qty integer:=1;v_cost bigint;v_reward bigint;v_msg text:='操作成功';v_cat record;v_cat2 record;
 v_array jsonb;v_new jsonb;v_obj jsonb;v_obj2 jsonb;v_tmp jsonb;v_dishes jsonb;v_plot jsonb;
 v_income bigint:=0;v_count integer:=0;v_index integer;v_at bigint;v_time bigint;v_level int;v_floor int;v_score int;v_ready bigint;
 v_rarity text;v_rarities text[]:=array['普通魚','進階魚','稀有魚','傳說魚','絕世魚','神話魚','永恆魚'];
 v_weights integer[]:=array[55,27,11,5,1,1,1];v_roll integer;v_idx int;v_mode text;
 v_price bigint;v_sell bigint;v_crops jsonb;v_more jsonb;v_d jsonb;v_kind text;v_currency text;
 v_bnk jsonb;v_own bigint:=0;v_pool bigint:=0;v_deposits bigint:=0;v_jailed timestamptz;
 v_target uuid;v_tstate jsonb;v_tgold bigint;v_amount bigint;
 v_record jsonb;v_result jsonb;v_orig uuid;v_pair jsonb;v_power bigint;
 v_house_prices bigint[]:=array[0,3000000,15000000,45000000,100000000,250000000];
 v_rents bigint[]:=array[0,4000,6500,10000,15000,23000,36000,55000,82000,122000,180000];
 v_upgrades bigint[]:=array[0,0,1500000,3000000,6000000,10000000,18000000,30000000,50000000,80000000,140000000];
begin
 if v_uid is null then raise exception 'LOGIN_REQUIRED';end if;
 if pg_catalog.length(coalesce(p_action,''))>45 or p_args is null or pg_catalog.jsonb_typeof(p_args)<>'object' then raise exception 'INVALID_ACTION';end if;
 if p_request_id is null then p_request_id:=pg_catalog.gen_random_uuid();end if;
 -- 交易全域鎖：玩家之間的金庫、轉帳與存檔更新不會競態；正式大量上線後可改細粒度鎖。
 perform pg_catalog.pg_advisory_xact_lock(2026,1118);
 select result into v_result from public.jiuli_secure_requests where user_id=v_uid and request_id=p_request_id;
 if found then return v_result;end if;
 insert into public.jiuli_secure_accounts(user_id,state) values(v_uid,public.jiuli_secure_default(v_now)) on conflict(user_id) do nothing;
 select state into v_st from public.jiuli_secure_accounts where user_id=v_uid for update;
 if v_st is null or pg_catalog.jsonb_typeof(v_st)<>'object' then raise exception 'INVALID_STATE';end if;
 v_before:=v_st;v_gold:=public.jiuli_secure_int(v_st,'gold');v_y:=public.jiuli_secure_int(v_st,'yuanbao');
 v_old_gold:=v_gold;v_old_y:=v_y;
 if v_gold>900000000000000 or v_y>900000000000000 then raise exception 'MIGRATED_BALANCE_REQUIRES_ADMIN_REVIEW';end if;
 -- 房產到期租金：由伺服器時間結算，離線玩家下一次開啟遊戲時入帳。
 v_array:='[]'::jsonb;
 for v_obj in select value from pg_catalog.jsonb_array_elements(coalesce(v_st->'houses','[]'::jsonb)) loop
  v_level:=greatest(1,least(10,(coalesce(v_obj->>'level','1'))::integer));
  v_at:=coalesce((v_obj->>'rentAt')::bigint,v_now);
  v_count:=greatest(0,least(720,((v_now-v_at)/3600000)::integer));
  if v_count>0 then
   v_income:=v_rents[v_level+1]*v_count;v_y:=v_y+v_income;
   v_st:=public.jiuli_secure_set(v_st,'rentTotal',public.jiuli_secure_int(v_st,'rentTotal')+v_income);
   v_obj:=pg_catalog.jsonb_set(v_obj,'{rentAt}',pg_catalog.to_jsonb(v_at+v_count*3600000));
  end if;
  v_array:=v_array||pg_catalog.jsonb_build_array(v_obj);
 end loop;
 v_st:=pg_catalog.jsonb_set(v_st,'{houses}',v_array,true);
 v_array:='[]'::jsonb;v_qty:=1;
 if coalesce(p_args->>'quantity','')~'^\d{1,3}$' then v_qty:=(p_args->>'quantity')::int;end if;
 if p_action='status' then v_msg:='已讀取安全雲端進度';
 elsif p_action='signin' then
  if v_st->>'signIn'=v_day then raise exception 'ALREADY_SIGNED_IN';end if;
  v_gold:=v_gold+2000;v_y:=v_y+888;
  v_st:=pg_catalog.jsonb_set(v_st,'{signIn}',pg_catalog.to_jsonb(v_day));
  v_st:=public.jiuli_secure_adjust(v_st,'chests','木製寶箱',1);
  v_msg:='今日簽到：金幣+2000、元寶+888、木製寶箱+1';
 elsif p_action='memberSignin' then
  if public.jiuli_secure_int(v_st,'vipUntil')<v_now then raise exception 'MEMBERSHIP_EXPIRED';end if;
  if v_st->>'memberSignIn'=v_day then raise exception 'MEMBER_SIGNED_TODAY';end if;
  v_name:=v_st->>'membership';
  v_reward:=case v_name when '貴族會員' then 888888 when '農場豪華會員' then 6000 when '農場普通會員' then 2000 else 888 end;
  v_y:=v_y+v_reward;
  v_st:=pg_catalog.jsonb_set(v_st,'{memberSignIn}',pg_catalog.to_jsonb(v_day));
  v_msg:='會員簽到取得'||v_reward||'元寶';
 elsif p_action='newbie' then
  if coalesce(v_st->>'newbieBonus','false')='true' then raise exception 'BONUS_ALREADY_CLAIMED';end if;
  v_y:=v_y+3000000;v_st:=pg_catalog.jsonb_set(v_st,'{newbieBonus}','true'::jsonb);v_msg:='領取一次性房產補助300萬元寶';
 elsif p_action='saveName' then
  if pg_catalog.length(v_name)<1 or pg_catalog.length(v_name)>12 then raise exception 'INVALID_NAME';end if;
  v_st:=pg_catalog.jsonb_set(v_st,'{name}',pg_catalog.to_jsonb(v_name));v_msg:='暱稱已更新';
 elsif p_action='fishCast' then
  if v_st->'fishing'<>'null'::jsonb and v_st->'fishing' is not null then raise exception 'ALREADY_FISHING';end if;
  v_at:=case when public.jiuli_secure_int(v_st,'speedCharges')>0 then 8000 else 16000 end;
  if v_at=8000 then v_st:=public.jiuli_secure_set(v_st,'speedCharges',public.jiuli_secure_int(v_st,'speedCharges')-1);end if;
  v_st:=pg_catalog.jsonb_set(v_st,'{fishing}',pg_catalog.jsonb_build_object('startedAt',v_now,'readyAt',v_now+v_at));v_msg:='拋竿成功，等待魚兒上鉤';
 elsif p_action='fishCollect' then
  v_obj:=v_st->'fishing';if v_obj is null or v_obj='null'::jsonb then raise exception 'NO_FISHING';end if;
  if public.jiuli_secure_int(v_obj,'readyAt')>v_now then raise exception 'NOT_READY';end if;
  v_roll:=(pg_catalog.floor(pg_catalog.random()*101)+1)::int;
  v_rarity:=case when v_roll<=55 then '普通魚' when v_roll<=82 then '進階魚' when v_roll<=93 then '稀有魚' when v_roll<=98 then '傳說魚' when v_roll<=99 then '絕世魚' when v_roll<=100 then '神話魚' else '永恆魚' end;
  if public.jiuli_secure_int(v_st,'baitCharges')>0 then
   v_st:=public.jiuli_secure_set(v_st,'baitCharges',public.jiuli_secure_int(v_st,'baitCharges')-1);
   if v_roll<=90 then v_rarity:='稀有魚';end if;
  end if;
  select name,attrs into v_cat from public.jiuli_secure_catalog where kind='fish' and category=v_rarity order by pg_catalog.random() limit 1;
  if v_cat.name is null then raise exception 'MISSING_FISH_CATALOG';end if;
  v_obj:=pg_catalog.jsonb_build_object('name',v_cat.name,'rarity',v_rarity,'price',(v_cat.attrs->>'price')::bigint);
  if pg_catalog.jsonb_array_length(coalesce(v_st->'fish','[]'::jsonb))>=10000 then raise exception 'FISH_POND_FULL';end if;
  v_st:=pg_catalog.jsonb_set(v_st,'{fish}',coalesce(v_st->'fish','[]'::jsonb)||pg_catalog.jsonb_build_array(v_obj));
  if not coalesce(v_st->'discovered','[]'::jsonb) @> pg_catalog.jsonb_build_array(v_cat.name) then
   v_st:=pg_catalog.jsonb_set(v_st,'{discovered}',coalesce(v_st->'discovered','[]'::jsonb)||pg_catalog.jsonb_build_array(v_cat.name));
  end if;
  v_st:=pg_catalog.jsonb_set(v_st,'{fishing}','null'::jsonb);
  v_st:=public.jiuli_secure_set(v_st,'xp',public.jiuli_secure_int(v_st,'xp')+10);
  v_st:=public.jiuli_secure_adjust(v_st,'stats','casts',1);
  if public.jiuli_secure_int(v_st,'autoCharges')>0 then v_st:=public.jiuli_secure_set(v_st,'autoCharges',public.jiuli_secure_int(v_st,'autoCharges')-1);end if;
  v_msg:='釣到'||v_rarity||'：'||v_cat.name;
 elsif p_action='sellFish' then
  v_mode:=coalesce(p_args->>'value','安全出售');
  if v_mode<>'全部' and v_mode<>'安全出售' and not (v_mode=any(v_rarities)) then raise exception 'INVALID_RARITY';end if;
  v_array:='[]'::jsonb;v_income:=0;v_count:=0;
  for v_obj in select value from pg_catalog.jsonb_array_elements(coalesce(v_st->'fish','[]'::jsonb)) loop
   if v_mode='全部' or v_mode='安全出售' and (v_obj->>'rarity')=any(array['普通魚','進階魚','稀有魚']) or v_obj->>'rarity'=v_mode then
    select attrs,category into v_cat from public.jiuli_secure_catalog where kind='fish' and name=v_obj->>'name';
    if v_cat.attrs is null or v_cat.category<>v_obj->>'rarity' then raise exception 'UNKNOWN_LEGACY_FISH_NEEDS_REVIEW';end if;
    v_income:=v_income+(v_cat.attrs->>'price')::bigint;v_count:=v_count+1;
   else v_array:=v_array||pg_catalog.jsonb_build_array(v_obj);end if;
  end loop;
  if v_count=0 then raise exception 'NO_FISH_TO_SELL';end if;
  v_gold:=v_gold+v_income;
  v_st:=pg_catalog.jsonb_set(v_st,'{fish}',v_array);
  v_st:=public.jiuli_secure_adjust(v_st,'stats','fishSold',v_count);
  v_msg:='賣出'||v_count||'條'||v_mode||'魚，金幣+'||v_income;
 elsif p_action='buySeed' then
  select attrs into v_cat from public.jiuli_secure_catalog where kind='seed' and name=v_name;
  if v_cat.attrs is null then raise exception 'UNKNOWN_SEED';end if;
  v_cost:=(v_cat.attrs->>'cost')::bigint;
  if v_gold<v_cost then raise exception 'NOT_ENOUGH_GOLD';end if;
  v_gold:=v_gold-v_cost;v_st:=public.jiuli_secure_adjust(v_st,'seeds',v_name,1);v_msg:='購買種子'||v_name;
 elsif p_action='plant' or p_action='plantAll' then
  v_name:=p_args->>'seed';
  select attrs into v_cat from public.jiuli_secure_catalog where kind='seed' and name=v_name;
  if v_cat.attrs is null then raise exception 'UNKNOWN_SEED';end if;
  v_level:=public.jiuli_secure_int(v_st,'farmLevel')::int;
  v_floor:=case when v_level>=27 then 10 when v_level>=21 then 9 when v_level>=16 then 8 when v_level>=12 then 7 when v_level>=8 then 6 when v_level>=5 then 5 when v_level>=3 then 4 else 3 end;
  v_array:=coalesce(v_st->'plots','[null,null,null,null,null,null,null,null,null,null]'::jsonb);
  v_count:=0;v_index:=coalesce((p_args->>'index')::integer,-1);
  if p_action='plant' and (v_index<0 or v_index>=v_floor) then raise exception 'INVALID_PLOT';end if;
  for v_i in 0..v_floor-1 loop
