   v_array:=v_array||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('crime',v_obj->>'crime','score',v_score,'won',v_score>=70,'at',v_now));
   v_st:=pg_catalog.jsonb_set(v_st,'{courtRecords}',v_array);v_st:=pg_catalog.jsonb_set(v_st,'{court}','null'::jsonb);
  end if;
 elsif p_action='startDelivery' then
  if v_st->'delivery' is not null and v_st->'delivery'<>'null'::jsonb then raise exception 'DELIVERY_ACTIVE';end if;
  if v_st->'tipOffer' is not null and v_st->'tipOffer'<>'null'::jsonb then raise exception 'TIP_WAITING';end if;
  v_array:=pg_catalog.array_to_json(array['透明人總經理','水豚教授','脾氣不好的阿嬤','外星王子','失眠的機器貓','包租婆','魔法師','月球廚師','火星郵差','靈貓皇后'])::jsonb;
  v_name:=v_array->>pg_catalog.floor(pg_catalog.random()*10)::int;
  v_obj:=pg_catalog.jsonb_build_object('order','奇幻料理外送','customer',v_name,'destination','九黎世界第'||(pg_catalog.floor(pg_catalog.random()*99)::int+1)||'區','obstacle','請安全送達','readyAt',v_now+(2+pg_catalog.floor(pg_catalog.random()*11)::int)*60000,'baseGold',1+pg_catalog.floor(pg_catalog.random()*5000)::int,'baseYuanbao',1+pg_catalog.floor(pg_catalog.random()*1000)::int,'tipEligible',pg_catalog.random()<0.1);
  v_st:=pg_catalog.jsonb_set(v_st,'{delivery}',v_obj);v_msg:='已接取隨機外送訂單';
 elsif p_action='finishDelivery' then
  v_obj:=v_st->'delivery';if v_obj is null or v_obj='null'::jsonb then raise exception 'NO_DELIVERY';end if;
  if public.jiuli_secure_int(v_obj,'readyAt')>v_now then raise exception 'DELIVERY_NOT_READY';end if;
  v_gold:=v_gold+public.jiuli_secure_int(v_obj,'baseGold');v_y:=v_y+public.jiuli_secure_int(v_obj,'baseYuanbao');
  v_st:=public.jiuli_secure_set(v_st,'xp',public.jiuli_secure_int(v_st,'xp')+25);
  v_st:=public.jiuli_secure_set(v_st,'deliveries',public.jiuli_secure_int(v_st,'deliveries')+1);
  v_st:=pg_catalog.jsonb_set(v_st,'{delivery}','null'::jsonb);
  if coalesce(v_obj->>'tipEligible','false')='true' then v_st:=pg_catalog.jsonb_set(v_st,'{tipOffer}',pg_catalog.jsonb_build_object('title',v_obj->>'order','createdAt',v_now));end if;
  v_array:=coalesce(v_st->'deliveryRecords','[]'::jsonb);
  v_array:=v_array||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('title',v_obj->>'order','customer',v_obj->>'customer','gold',v_obj->'baseGold','yuanbao',v_obj->'baseYuanbao','tip',v_obj->'tipEligible','finishedAt',v_now));
  v_st:=pg_catalog.jsonb_set(v_st,'{deliveryRecords}',v_array);v_msg:='外送報酬已入帳，小費請自行選擇';
 elsif p_action='claimTip' then
  if v_st->'tipOffer' is null or v_st->'tipOffer'='null'::jsonb then raise exception 'NO_TIP';end if;
  v_currency:=p_args->>'value';if v_currency not in ('gold','yuanbao') then raise exception 'INVALID_CURRENCY';end if;
  if v_currency='gold' then v_reward:=1000+pg_catalog.floor(pg_catalog.random()*14001)::int;v_gold:=v_gold+v_reward;
  else v_reward:=500+pg_catalog.floor(pg_catalog.random()*4501)::int;v_y:=v_y+v_reward;end if;
  v_st:=pg_catalog.jsonb_set(v_st,'{tipOffer}','null'::jsonb);v_msg:='已領取'||v_reward||v_currency||'小費';
 elsif p_action='buyShop' or p_action='buyChest' then
  if v_qty not in (1,5,10) then raise exception 'INVALID_QUANTITY';end if;
  if p_action='buyChest' then v_qty:=1;end if;
  select currency,price,item_type into v_cat from public.jiuli_secure_shop where name=v_name;
  if v_cat.currency is null then raise exception 'SHOP_PRODUCT_NOT_AVAILABLE';end if;
  if p_action='buyChest' and v_cat.item_type<>'chest' then raise exception 'INVALID_CHEST';end if;
  if v_name='永恆寶箱' and public.jiuli_secure_int(v_st,'vipUntil')<v_now then raise exception 'VIP_REQUIRED';end if;
  v_cost:=v_cat.price*v_qty;
  if v_cat.currency='gold' then
   if v_gold<v_cost then raise exception 'NOT_ENOUGH_GOLD';end if;v_gold:=v_gold-v_cost;
  else
   if v_y<v_cost then raise exception 'NOT_ENOUGH_YUANBAO';end if;v_y:=v_y-v_cost;
  end if;
  if v_cat.item_type='fragments' then v_st:=public.jiuli_secure_set(v_st,'fragments',public.jiuli_secure_int(v_st,'fragments')+v_qty);
  elsif v_cat.item_type='fruit' then v_st:=public.jiuli_secure_set(v_st,'fruit',public.jiuli_secure_int(v_st,'fruit')+v_qty);
  elsif v_cat.item_type='chest' then v_st:=public.jiuli_secure_adjust(v_st,'chests',v_name,v_qty);
  else v_st:=public.jiuli_secure_adjust(v_st,'items',v_name,v_qty);end if;
  v_msg:='購買'||v_name||'×'||v_qty||' 成功';
 elsif p_action in ('useShopItem','useFishItem') then
  if public.jiuli_secure_int(v_st->'items',v_name)<1 then raise exception 'ITEM_NOT_OWNED';end if;
  if v_name not in ('時光加速','自動提竿','稀有魚餌','高級魚餌','幸運符','料理加速券','種子補給箱') then raise exception 'ITEM_EFFECT_NOT_READY';end if;
  if v_name='料理加速券' then
   v_array:='[]'::jsonb;v_i:=0;
   for v_obj in select value from pg_catalog.jsonb_array_elements(coalesce(v_st->'kitchen','[]'::jsonb)) loop
    if v_i=0 and public.jiuli_secure_int(v_obj,'readyAt')>v_now then
     v_obj:=pg_catalog.jsonb_set(v_obj,'{readyAt}',pg_catalog.to_jsonb(v_now));v_i:=1;
    end if;
    v_array:=v_array||pg_catalog.jsonb_build_array(v_obj);
   end loop;
   if v_i=0 then raise exception 'NO_COOKING_TO_SPEED';end if;
   v_st:=pg_catalog.jsonb_set(v_st,'{kitchen}',v_array);
  elsif v_name='種子補給箱' then
   for v_i in 1..5 loop
    select name into v_text from public.jiuli_secure_catalog where kind='seed' and category='' order by pg_catalog.random() limit 1;
    if v_text is null then raise exception 'MISSING_SEED_CATALOG';end if;
    v_st:=public.jiuli_secure_adjust(v_st,'seeds',v_text,1);
   end loop;
  elsif v_name='時光加速' then
   v_st:=public.jiuli_secure_set(v_st,'speedCharges',public.jiuli_secure_int(v_st,'speedCharges')+5);
   if v_st->'fishing'<>'null'::jsonb and v_st->'fishing' is not null then
    v_obj:=v_st->'fishing';v_obj:=pg_catalog.jsonb_set(v_obj,'{readyAt}',pg_catalog.to_jsonb(greatest(v_now+2000,public.jiuli_secure_int(v_obj,'readyAt')-8000)));
    v_st:=pg_catalog.jsonb_set(v_st,'{fishing}',v_obj);
   end if;
  elsif v_name='自動提竿' then v_st:=public.jiuli_secure_set(v_st,'autoCharges',public.jiuli_secure_int(v_st,'autoCharges')+5);
  else v_st:=public.jiuli_secure_set(v_st,'baitCharges',public.jiuli_secure_int(v_st,'baitCharges')+case when v_name='幸運符' then 10 else 5 end);end if;
  v_st:=public.jiuli_secure_adjust(v_st,'items',v_name,-1);v_msg:='使用'||v_name||' 成功';
 elsif p_action in ('openChest','openAllChests') then
  if p_action='openChest' then
   if v_name='' then raise exception 'NO_CHEST_NAME';end if;
   if public.jiuli_secure_int(v_st->'chests',v_name)<1 then raise exception 'CHEST_NOT_OWNED';end if;
  end if;
  v_count:=0;v_mode:=coalesce(v_name,'');
  for v_i in 1..100 loop
   if p_action='openAllChests' then
    select key into v_name from pg_catalog.jsonb_each(coalesce(v_st->'chests','{}'::jsonb))
     where public.jiuli_secure_int(v_st->'chests',key)>0 order by key limit 1;
    if v_name is null then exit;end if;
   end if;
   if v_name not in ('普通寶箱','精良寶箱','精緻寶箱','稀有寶箱','傳說寶箱','絕世寶箱','神秘寶箱','永恆寶箱','究極寶箱','天域寶箱','鴻蒙寶箱','木製寶箱','星光寶箱') then raise exception 'UNKNOWN_CHEST';end if;
   v_st:=public.jiuli_secure_adjust(v_st,'chests',v_name,-1);
   if v_name in ('鴻蒙寶箱','天域寶箱','究極寶箱','永恆寶箱') then
    v_reward:=case v_name when '鴻蒙寶箱' then 500000+pg_catalog.floor(pg_catalog.random()*1000001)::bigint
      when '天域寶箱' then 199998+pg_catalog.floor(pg_catalog.random()*800003)::bigint
      when '究極寶箱' then 99999+pg_catalog.floor(pg_catalog.random()*400002)::bigint
      else 10000+pg_catalog.floor(pg_catalog.random()*90000)::bigint end;
    v_y:=v_y+v_reward;
    if v_name<>'永恆寶箱' then
     v_st:=public.jiuli_secure_set(v_st,'fragments',public.jiuli_secure_int(v_st,'fragments')+5+pg_catalog.floor(pg_catalog.random()*6)::bigint);
    else
     v_st:=public.jiuli_secure_adjust(v_st,'items','時光加速',1);
    end if;
    if v_name='鴻蒙寶箱' then v_st:=public.jiuli_secure_set(v_st,'fruit',public.jiuli_secure_int(v_st,'fruit')+1);end if;
   else
    v_reward:=case when v_name in ('木製寶箱','普通寶箱','神秘寶箱') then 100+pg_catalog.floor(pg_catalog.random()*1301)::bigint
     when v_name in ('精良寶箱','精緻寶箱','星光寶箱') then 500+pg_catalog.floor(pg_catalog.random()*3000)::bigint
     when v_name='稀有寶箱' then 2000+pg_catalog.floor(pg_catalog.random()*6001)::bigint
     when v_name='傳說寶箱' then 5000+pg_catalog.floor(pg_catalog.random()*15001)::bigint
     else 20000+pg_catalog.floor(pg_catalog.random()*80001)::bigint end;
    v_gold:=v_gold+v_reward;
    if pg_catalog.random()<0.25 then v_st:=public.jiuli_secure_adjust(v_st,'items','稀有魚餌',1);end if;
   end if;
   v_count:=v_count+1;
   if p_action='openChest' then exit;end if;
  end loop;
  if v_count=0 then raise exception 'NO_CHESTS';end if;
  v_msg:='已開啟'||v_count||'個寶箱；全部獎勵由伺服器派發';
 elsif p_action='buyMembership' then
  v_cost:=case v_name when '普通會員' then 5000 when '農場普通會員' then 8000
     when '農場豪華會員' then 100000 when '貴族會員' then 2000000 else 0 end;
  if v_cost=0 then raise exception 'UNKNOWN_MEMBER_TYPE';end if;
  if v_y<v_cost then raise exception 'NOT_ENOUGH_YUANBAO';end if;
  v_y:=v_y-v_cost;
  v_at:=case when v_name='貴族會員' then 60 when v_name in ('農場豪華會員') then 30 else 7 end;
  v_st:=pg_catalog.jsonb_set(v_st,'{membership}',pg_catalog.to_jsonb(v_name));
  v_st:=public.jiuli_secure_set(v_st,'vipUntil',greatest(v_now,public.jiuli_secure_int(v_st,'vipUntil'))+v_at*86400000);
  v_msg:='啟用'||v_name||'，有效期'||v_at||'天';

 elsif p_action='teamCreate' then
  if exists(select 1 from public.jiuli_secure_team_members m join public.jiuli_secure_teams t on t.id=m.team_id
            where m.user_id=v_uid and t.status='open') then raise exception 'ALREADY_IN_TEAM';end if;
  v_text:=pg_catalog.upper(pg_catalog.substr(pg_catalog.replace(pg_catalog.gen_random_uuid()::text,'-',''),1,8));
  insert into public.jiuli_secure_teams(code,leader_id) values(v_text,v_uid) returning id into v_orig;
  insert into public.jiuli_secure_team_members(team_id,user_id) values(v_orig,v_uid);
  v_msg:='組隊成功，邀請代碼：'||v_text;
 elsif p_action='teamJoin' then
  v_text:=pg_catalog.upper(pg_catalog.btrim(v_text));
  if v_text !~ '^[A-F0-9]{8}$' then raise exception 'INVALID_TEAM_CODE';end if;
  select id into v_orig from public.jiuli_secure_teams where code=v_text and status='open' for update;
  if v_orig is null then raise exception 'TEAM_NOT_FOUND';end if;
  if exists(select 1 from public.jiuli_secure_team_members m join public.jiuli_secure_teams t on t.id=m.team_id
            where m.user_id=v_uid and t.status='open') then raise exception 'ALREADY_IN_TEAM';end if;
  select count(*) into v_count from public.jiuli_secure_team_members where team_id=v_orig;
  if v_count>=5 then raise exception 'TEAM_FULL';end if;
  insert into public.jiuli_secure_team_members(team_id,user_id) values(v_orig,v_uid);
  v_msg:='加入組隊成功';
 elsif p_action='teamStart' then
  select id into v_orig from public.jiuli_secure_teams where leader_id=v_uid and status='open' order by created_at desc limit 1 for update;
  if v_orig is null then raise exception 'ONLY_LEADER_CAN_START';end if;
  select count(*) into v_count from public.jiuli_secure_team_members where team_id=v_orig;
  if v_count<2 or v_count>5 then raise exception 'TEAM_NEEDS_2_TO_5';end if;
  -- 所有組員皆須先登入過新版，且本日仍有副本額度。
  v_power:=0;
  for v_pair in select pg_catalog.jsonb_build_object('uid',m.user_id,'state',a.state) from public.jiuli_secure_team_members m
                  join public.jiuli_secure_accounts a on a.user_id=m.user_id where m.team_id=v_orig loop
    v_obj:=v_pair->'state';
    if v_obj->>'dungeonDate'=v_day and public.jiuli_secure_int(v_obj,'dungeonRuns')>=3 then raise exception 'TEAM_MEMBER_LIMIT';end if;
    v_n:=220+public.jiuli_secure_int(v_obj,'level')*35;
    for v_d in select value from pg_catalog.jsonb_array_elements(coalesce(v_obj->'pets','[]'::jsonb)) loop
     if v_d->>'name'=v_obj->>'activePet' then
      v_n:=v_n+95+public.jiuli_secure_int(v_d,'level')*175+public.jiuli_secure_int(v_d,'fruit')*15;
     end if;
    end loop;
    v_power:=v_power+v_n;
  end loop;
  v_floor:=0;
  for v_j in 1..100 loop if v_power>=100+90*v_j+10*v_j*v_j then v_floor:=v_j;else exit;end if;end loop;
  if v_floor<1 then raise exception 'TEAM_POWER_LOW';end if;
  v_name:=case when v_floor>=95 then '鴻蒙寶箱' when v_floor>=75 then '天域寶箱' when v_floor>=55 then '究極寶箱' when v_floor>=35 then '絕世寶箱' else '傳說寶箱' end;
  for v_pair in select pg_catalog.jsonb_build_object('uid',m.user_id,'state',a.state) from public.jiuli_secure_team_members m
                  join public.jiuli_secure_accounts a on a.user_id=m.user_id where m.team_id=v_orig loop
    v_obj:=v_pair->'state';
    if v_obj->>'dungeonDate'<>v_day then v_obj:=pg_catalog.jsonb_set(v_obj,'{dungeonDate}',pg_catalog.to_jsonb(v_day));v_obj:=public.jiuli_secure_set(v_obj,'dungeonRuns',0);end if;
    v_obj:=public.jiuli_secure_set(v_obj,'dungeonRuns',public.jiuli_secure_int(v_obj,'dungeonRuns')+1);
    v_obj:=public.jiuli_secure_set(v_obj,'dungeonMax',greatest(v_floor,public.jiuli_secure_int(v_obj,'dungeonMax')));
    v_obj:=public.jiuli_secure_adjust(v_obj,'chests',v_name,1+v_floor/30);
    v_obj:=public.jiuli_secure_set(v_obj,'fragments',public.jiuli_secure_int(v_obj,'fragments')+5+v_floor/15);
    v_obj:=public.jiuli_secure_set(v_obj,'gold',public.jiuli_secure_int(v_obj,'gold')+v_floor*350);
    v_obj:=public.jiuli_secure_set(v_obj,'yuanbao',public.jiuli_secure_int(v_obj,'yuanbao')+v_floor*150);
    update public.jiuli_secure_accounts set state=v_obj,revision=revision+1,updated_at=now() where user_id=(v_pair->>'uid')::uuid;
    if (v_pair->>'uid')::uuid=v_uid then
      v_st:=v_obj;v_gold:=public.jiuli_secure_int(v_obj,'gold');v_y:=public.jiuli_secure_int(v_obj,'yuanbao');
    end if;
  end loop;
  update public.jiuli_secure_teams set status='finished' where id=v_orig;
  v_msg:='組隊'||v_count||'人挑戰'||v_floor||'層完成，所有成員獎勵已發';
 elsif p_action in ('web13BankStatus','web13BankDeposit','web13BankWithdraw','web13BankRob','web13BankEscape','web13BankBail','web13BankTransfer','web13VentureGold','web13VentureYuanbao','web13LegacyWithdraw') then
  v_amount:=coalesce((p_args->>'amount')::bigint,0);
  select balance into v_own from public.jiuli_secure_bank where user_id=v_uid for update;
  v_own:=coalesce(v_own,0);
  select amount into v_pool from public.jiuli_secure_bank_pool where id=true for update;
  select until_at into v_jailed from public.jiuli_secure_jail where user_id=v_uid for update;
  if p_action in ('web13BankDeposit','web13BankWithdraw','web13BankTransfer','web13VentureGold','web13VentureYuanbao') and (v_amount<1 or v_amount>10000000) then raise exception 'INVALID_AMOUNT';end if;
  if p_action='web13BankStatus' then v_msg:='銀行餘額已更新';
  elsif p_action='web13LegacyWithdraw' then
   v_n:=public.jiuli_secure_int(v_st,'bank');
   if v_n<1 or v_n>10000000 then raise exception 'LEGACY_BANK_REVIEW_REQUIRED';end if;
   v_gold:=v_gold+v_n;v_st:=public.jiuli_secure_set(v_st,'bank',0);v_msg:='已領回舊私人銀行'||v_n||'金幣';
  elsif p_action='web13BankDeposit' then
   if v_gold<v_amount then raise exception 'NOT_ENOUGH_GOLD';end if;
   v_gold:=v_gold-v_amount;
   insert into public.jiuli_secure_bank(user_id,balance) values(v_uid,v_amount) on conflict(user_id) do update set balance=public.jiuli_secure_bank.balance+excluded.balance;
   v_msg:='成功存入金庫'||v_amount||'金幣';
  elsif p_action='web13BankWithdraw' then
   if v_own<v_amount then raise exception 'NOT_ENOUGH_DEPOSIT';end if;
   update public.jiuli_secure_bank set balance=balance-v_amount where user_id=v_uid;
   v_gold:=v_gold+v_amount;v_msg:='成功提領'||v_amount||'金幣';
  elsif p_action='web13BankRob' then
   if v_jailed is not null and v_jailed>now() then raise exception 'JAILED';end if;
   select coalesce(sum(balance),0) into v_deposits from public.jiuli_secure_bank;
   v_n:=coalesce(v_pool,0)+v_deposits;
   if v_n<10 then raise exception 'VAULT_EMPTY';end if;
   if pg_catalog.random()<0.35 then
    v_amount:=least(100000,greatest(1,v_n/10));
    v_amount:=1+pg_catalog.floor(pg_catalog.random()*v_amount)::bigint;
    if v_pool>=v_amount then update public.jiuli_secure_bank_pool set amount=amount-v_amount where id=true;
    else
     v_reward:=v_amount-v_pool;
     select user_id,balance into v_target,v_tgold from public.jiuli_secure_bank where balance>=v_reward order by balance desc limit 1 for update;
     if v_target is null then v_amount:=coalesce(v_pool,0);update public.jiuli_secure_bank_pool set amount=0 where id=true;
     else update public.jiuli_secure_bank set balance=balance-v_reward where user_id=v_target;
       update public.jiuli_secure_bank_pool set amount=0 where id=true;end if;
    end if;
    v_gold:=v_gold+v_amount;v_msg:='搶銀行成功！取得'||v_amount||'金幣';
   else
    if pg_catalog.random()<0.35 then
     insert into public.jiuli_secure_jail(user_id,until_at) values(v_uid,now()+interval '2 hours')
      on conflict(user_id) do update set until_at=excluded.until_at;
     v_msg:='搶銀行失敗，被關入監獄2小時';
    else
     v_amount:=least(v_gold,20+pg_catalog.floor(pg_catalog.random()*181)::bigint);
     v_gold:=v_gold-v_amount;
     update public.jiuli_secure_bank_pool set amount=amount+v_amount where id=true;
     v_msg:='搶銀行失敗，罰金'||v_amount||'金幣';
    end if;
   end if;
  elsif p_action='web13BankEscape' then
   if v_jailed is null or v_jailed<=now() then raise exception 'NOT_JAILED';end if;
   if v_gold<3000 then raise exception 'NOT_ENOUGH_GOLD';end if;
   v_gold:=v_gold-3000;
   if pg_catalog.random()<0.45 then update public.jiuli_secure_jail set until_at=null where user_id=v_uid;v_msg:='逃獄成功';
   else update public.jiuli_secure_bank_pool set amount=amount+3000 where id=true;v_msg:='逃獄失敗';end if;
  elsif p_action='web13BankBail' or p_action='web13BankTransfer' then
   select user_id into v_target from public.jiuli_web_profiles where lower(handle)=lower(pg_catalog.btrim(v_text)) limit 1;
   if v_target is null or v_target=v_uid then raise exception 'INVALID_TARGET';end if;
   if p_action='web13BankBail' then
    select until_at into v_jailed from public.jiuli_secure_jail where user_id=v_target for update;
    if v_jailed is null or v_jailed<=now() then raise exception 'NOT_JAILED';end if;
    if v_gold<20000 then raise exception 'NOT_ENOUGH_GOLD';end if;
    v_gold:=v_gold-20000;
    update public.jiuli_secure_jail set until_at=null where user_id=v_target;
    update public.jiuli_secure_bank_pool set amount=amount+20000 where id=true;
    v_msg:='替好友保釋成功';
   else
    if v_gold<v_amount then raise exception 'NOT_ENOUGH_GOLD';end if;
    select state into v_tstate from public.jiuli_secure_accounts where user_id=v_target for update;
    if v_tstate is null then raise exception 'TARGET_NOT_ACTIVATED';end if;
    v_tgold:=public.jiuli_secure_int(v_tstate,'gold');
    if v_tgold+v_amount>900000000000000 then raise exception 'TARGET_BALANCE_LIMIT';end if;
    update public.jiuli_secure_accounts set state=public.jiuli_secure_set(v_tstate,'gold',v_tgold+v_amount),revision=revision+1,updated_at=now() where user_id=v_target;
    v_gold:=v_gold-v_amount;v_msg:='轉帳'||v_amount||'金幣成功';
   end if;
  else
   if v_jailed is not null and v_jailed>now() then raise exception 'JAILED';end if;
   if v_amount<100 or v_amount>50000 then raise exception 'VENTURE_AMOUNT_LIMIT';end if;
   v_i:=coalesce((p_args->>'project')::integer,0);
   if v_i<1 or v_i>9 then raise exception 'INVALID_VENTURE';end if;
   v_reward:=v_amount*(case v_i when 1 then 120 when 2 then 140 when 3 then 160 when 4 then 160 when 5 then 180 when 6 then 200 when 7 then 220 when 8 then 240 else 260 end)/100;
   if p_action='web13VentureGold' then
    if v_gold<v_amount then raise exception 'NOT_ENOUGH_GOLD';end if;
    v_gold:=v_gold-v_amount;
    if pg_catalog.random()<0.60 then v_gold:=v_gold+v_reward;v_msg:='創業成功！取得'||v_reward||'金幣';
    else update public.jiuli_secure_bank_pool set amount=amount+v_amount where id=true;v_msg:='創業失敗，金幣投入獎池';end if;
   else
    if v_y<v_amount then raise exception 'NOT_ENOUGH_YUANBAO';end if;
    v_y:=v_y-v_amount;
    if pg_catalog.random()<0.60 then v_y:=v_y+v_reward;v_msg:='元寶創業成功，獲得'||v_reward||'元寶';
    else v_msg:='元寶創業失敗';end if;
   end if;
  end if;
 elsif p_action='bombStart' then
  if coalesce(v_st->'bomb'->>'answer','0')<>'0' then raise exception 'BOMB_ACTIVE';end if;
  insert into public.jiuli_secure_bombs(user_id,answer) values(v_uid,1+pg_catalog.floor(pg_catalog.random()*100)::int)
  on conflict(user_id) do update set answer=excluded.answer;
  v_st:=pg_catalog.jsonb_set(v_st,'{bomb}','{"answer":-1,"tries":0,"low":1,"high":100}'::jsonb);v_msg:='數字炸彈開局，答案由伺服器保管';
 elsif p_action='bombGuess' then
  v_n:=coalesce((p_args->>'guess')::bigint,-1);if v_n<1 or v_n>100 then raise exception 'INVALID_GUESS';end if;
  v_obj:=v_st->'bomb';if public.jiuli_secure_int(v_obj,'tries')>=8 or coalesce(v_obj->>'answer','0')='0' then raise exception 'NO_BOMB';end if;
  select answer into v_i from public.jiuli_secure_bombs where user_id=v_uid;
  if v_i is null then raise exception 'NO_BOMB';end if;
  v_count:=public.jiuli_secure_int(v_obj,'tries')::int+1;
  if v_n=v_i then
   v_gold:=v_gold+2000;v_st:=pg_catalog.jsonb_set(v_st,'{bomb}','{"answer":0,"tries":0,"low":1,"high":100}'::jsonb);
   delete from public.jiuli_secure_bombs where user_id=v_uid;v_msg:='猜中了！獲得2000金幣';
  elsif v_count>=8 then
   v_st:=pg_catalog.jsonb_set(v_st,'{bomb}','{"answer":0,"tries":0,"low":1,"high":100}'::jsonb);
   delete from public.jiuli_secure_bombs where user_id=v_uid;v_msg:='炸彈爆炸了！答案是'||v_i;
  else
   v_obj:=pg_catalog.jsonb_set(v_obj,'{tries}',pg_catalog.to_jsonb(v_count));
   if v_n>v_i then v_obj:=pg_catalog.jsonb_set(v_obj,'{high}',pg_catalog.to_jsonb(least(public.jiuli_secure_int(v_obj,'high'),v_n-1)));
   else v_obj:=pg_catalog.jsonb_set(v_obj,'{low}',pg_catalog.to_jsonb(greatest(public.jiuli_secure_int(v_obj,'low'),v_n+1)));end if;
   v_st:=pg_catalog.jsonb_set(v_st,'{bomb}',v_obj);v_msg:='猜錯了，請繼續';
  end if;
 elsif p_action='bombQuit' then
  delete from public.jiuli_secure_bombs where user_id=v_uid;
  v_st:=pg_catalog.jsonb_set(v_st,'{bomb}','{"answer":0,"tries":0,"low":1,"high":100}'::jsonb);v_msg:='已放棄這局';
 else
  raise exception 'SERVER_ACTION_NOT_YET_IMPLEMENTED: %',p_action;
 end if;
 -- 経験、農場等級只在伺服器升級，客戶端無法直接加等級兌獎。
 for v_j in 1..100 loop
  v_level:=greatest(1,public.jiuli_secure_int(v_st,'level')::int);
  if public.jiuli_secure_int(v_st,'xp') < v_level*130 then exit;end if;
  v_st:=public.jiuli_secure_set(v_st,'xp',public.jiuli_secure_int(v_st,'xp')-v_level*130);
  v_st:=public.jiuli_secure_set(v_st,'level',v_level+1);v_y:=v_y+1000;
 end loop;
 for v_j in 1..100 loop
  v_level:=greatest(1,public.jiuli_secure_int(v_st,'farmLevel')::int);
  if public.jiuli_secure_int(v_st,'farmXp') < 120+(v_level-1)*50 then exit;end if;
  v_st:=public.jiuli_secure_set(v_st,'farmXp',public.jiuli_secure_int(v_st,'farmXp')-(120+(v_level-1)*50));
  v_st:=public.jiuli_secure_set(v_st,'farmLevel',v_level+1);
 end loop;
 if v_gold<0 or v_y<0 or v_gold>900000000000000 or v_y>900000000000000 then raise exception 'ECONOMY_LIMIT';end if;
 v_st:=public.jiuli_secure_set(v_st,'gold',v_gold);v_st:=public.jiuli_secure_set(v_st,'yuanbao',v_y);
 if p_action<>'status' then
  v_array:=coalesce(v_st->'activity','[]'::jsonb);
  v_array:=pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('text',v_msg,'at',v_now))||v_array;
  v_st:=pg_catalog.jsonb_set(v_st,'{activity}',(select coalesce(pg_catalog.jsonb_agg(v),'[]'::jsonb) from (select v from pg_catalog.jsonb_array_elements(v_array) as t(v) limit 45) t));
 end if;
 if p_action<>'status' or v_gold<>v_old_gold or v_y<>v_old_y then
   update public.jiuli_secure_accounts set state=v_st,revision=revision+1,updated_at=now() where user_id=v_uid;
 end if;
 if p_action<>'status' then
  insert into public.jiuli_secure_events(user_id,action,note,before_gold,after_gold,before_yuanbao,after_yuanbao)
  values(v_uid,p_action,v_msg,v_old_gold,v_gold,v_old_y,v_y);
 end if;
 select coalesce(sum(balance),0) into v_deposits from public.jiuli_secure_bank;
 select amount into v_pool from public.jiuli_secure_bank_pool where id=true;
 select balance into v_own from public.jiuli_secure_bank where user_id=v_uid;
 select until_at into v_jailed from public.jiuli_secure_jail where user_id=v_uid;
 v_bnk:=pg_catalog.jsonb_build_object('own',coalesce(v_own,0),'pool',coalesce(v_pool,0),'deposits',v_deposits,'vault',v_deposits+coalesce(v_pool,0),'jailed_until',v_jailed);
 select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name',q.name,'rate',2+(pg_catalog.get_byte(pg_catalog.decode(pg_catalog.md5(q.name||(v_now/3600000)::text),'hex'),0)%2))), '[]'::jsonb)
 into v_more from (
   select name from public.jiuli_secure_catalog where kind='seed'
   order by case when public.jiuli_secure_int(v_st->'crops',name)>=5 then 0 else 1 end,
            pg_catalog.md5(name||(v_now/3600000)::text) limit 5
 ) q;
 select pg_catalog.jsonb_build_object('code',t.code,'count',pg_catalog.count(m.user_id),'leader',t.leader_id=v_uid)
 into v_pair from public.jiuli_secure_teams t join public.jiuli_secure_team_members m on m.team_id=t.id
 where t.status='open' and t.id=(select m2.team_id from public.jiuli_secure_team_members m2
   join public.jiuli_secure_teams t2 on t2.id=m2.team_id
   where m2.user_id=v_uid and t2.status='open' order by t2.created_at desc limit 1)
 group by t.id,t.code,t.leader_id;
 v_result:=pg_catalog.jsonb_build_object('state',v_st,'message',v_msg,'revision',(select revision from public.jiuli_secure_accounts where user_id=v_uid),'bank',v_bnk,'market_offers',v_more,'team',v_pair,'server_time',v_now);
 insert into public.jiuli_secure_requests(user_id,request_id,action,result) values(v_uid,p_request_id,p_action,v_result);
 return v_result;
end;
$game$;
revoke all on function public.jiuli_secure_game(text,jsonb,uuid) from public,anon,authenticated;
grant execute on function public.jiuli_secure_game(text,jsonb,uuid) to authenticated;


-- 此檔必須與前面所有 SQL 在同一交易執行，成功後立即凍結舊的前端任意存檔。
-- 舊表仍保留作唯讀歷史快照；不要刪除舊玩家資料。
revoke execute on function public.jiuli_web_save(bigint,jsonb) from public,anon,authenticated;
revoke update,insert,delete on public.jiuli_web_saves from public,anon,authenticated;
-- 舊 WEB 1.3 銀行函式引用可被網頁任意上傳的錢包；禁止舊客戶端繼續呼叫。
do $do$ begin
 if to_regprocedure('public.jiuli_web_bank_action(text,bigint,text)') is not null then
  execute 'revoke execute on function public.jiuli_web_bank_action(text,bigint,text) from public,anon,authenticated';
 end if;
end $do$;
-- 清除歷史過期的請求記錄應由管理員之後用排程進行，玩家不能刪除紀錄。
-- 執行結束後，可以在 SQL Editor 驗證權限，不能只靠本次 SQL 的「success」判斷已完全安全。

-- WEB 1.5 一體化好友與動畫更新：SQL 社交權威交易。
-- 九黎靈貓 WEB 1.5 好友、贈禮、互動及無邀請碼隊伍邀請
-- 需在 WEB 1.4 安全帳本與 jiuli_web_profiles 安裝後部署。
-- 權威資產只從 jiuli_secure_accounts 轉移，未登入不能發送任何好友操作。
create table if not exists public.jiuli_social_friends (
 user_a uuid not null references auth.users(id) on delete cascade,
 user_b uuid not null references auth.users(id) on delete cascade,
 requested_by uuid not null references auth.users(id) on delete cascade,
 status text not null check(status in ('pending','accepted','declined','blocked')),
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now(),
 primary key(user_a,user_b),
 check(user_a<user_b),check(requested_by in(user_a,user_b))
);
create index if not exists jiuli_social_friends_by_b on public.jiuli_social_friends(user_b,status);
create table if not exists public.jiuli_social_team_invites (
 id uuid primary key default gen_random_uuid(),
 team_id uuid not null references public.jiuli_secure_teams(id) on delete cascade,
 sender_id uuid not null references auth.users(id) on delete cascade,
 target_id uuid not null references auth.users(id) on delete cascade,
 status text not null default 'pending' check(status in ('pending','accepted','declined','expired')),
 created_at timestamptz not null default now(),
 expires_at timestamptz not null default (now()+interval '48 hours'),
 unique(team_id,target_id),check(sender_id<>target_id)
);
create index if not exists jiuli_social_invites_target on public.jiuli_social_team_invites(target_id,status);
create table if not exists public.jiuli_social_gift_log (
 id bigint generated always as identity primary key,
 sender_id uuid not null references auth.users(id) on delete cascade,
 recipient_id uuid not null references auth.users(id) on delete cascade,
 kind text not null,
 item_name text not null default '',
 quantity integer not null check(quantity>0),
 created_at timestamptz not null default now()
);
create index if not exists jiuli_social_gift_sender on public.jiuli_social_gift_log(sender_id,created_at desc);
create table if not exists public.jiuli_social_interactions (
 id bigint generated always as identity primary key,
 sender_id uuid not null references auth.users(id) on delete cascade,
 recipient_id uuid not null references auth.users(id) on delete cascade,
 kind text not null,
 created_at timestamptz not null default now()
);
create index if not exists jiuli_social_interactions_day on public.jiuli_social_interactions(sender_id,recipient_id,created_at desc);
create table if not exists public.jiuli_social_requests (
 user_id uuid not null references auth.users(id) on delete cascade,
 request_id uuid not null,
 result jsonb not null,
 created_at timestamptz not null default now(),
 primary key(user_id,request_id)
);

alter table public.jiuli_social_friends enable row level security;
alter table public.jiuli_social_team_invites enable row level security;
alter table public.jiuli_social_gift_log enable row level security;
alter table public.jiuli_social_interactions enable row level security;
alter table public.jiuli_social_requests enable row level security;
revoke all on public.jiuli_social_friends,public.jiuli_social_team_invites,
 public.jiuli_social_gift_log,public.jiuli_social_interactions,public.jiuli_social_requests from public,anon,authenticated;

create or replace function public.jiuli_social_snapshot(p_search text default '')
returns jsonb language plpgsql security definer set search_path='' as $social_view$
declare
 v_uid uuid:=auth.uid();v_name text:=pg_catalog.lower(pg_catalog.btrim(coalesce(p_search,'')));
 v_friends jsonb;v_in jsonb;v_out jsonb;v_invites jsonb;v_match jsonb;
 v_team jsonb;v_recent jsonb;
begin
 if v_uid is null then raise exception 'LOGIN_REQUIRED';end if;
 if pg_catalog.length(v_name)>32 then raise exception 'INVALID_HANDLE';end if;
 select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
  'user_id',p.user_id,'handle',p.handle,'display_name',p.display_name,
  'level',coalesce((case when a.state->>'level'~'^[0-9]{1,6}$' then (a.state->>'level')::int else 1 end),1),
  'pet',coalesce(a.state->>'activePet',''),
  'pet_level',(select coalesce(max((case when pet->>'level'~'^[0-9]{1,5}$' then (pet->>'level')::int else 1 end)),0)
        from pg_catalog.jsonb_array_elements(coalesce(a.state->'pets','[]'::jsonb)) pet where pet->>'name'=a.state->>'activePet'),
  'charisma',public.jiuli_secure_int(a.state,'charisma'),
  'generosity',public.jiuli_secure_int(a.state,'generosity')) order by p.handle),'[]'::jsonb)
 into v_friends
 from public.jiuli_social_friends f
 join public.jiuli_web_profiles p on p.user_id=(case when f.user_a=v_uid then f.user_b else f.user_a end)
 left join public.jiuli_secure_accounts a on a.user_id=p.user_id
 where f.status='accepted' and (f.user_a=v_uid or f.user_b=v_uid);
 select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('user_id',p.user_id,'handle',p.handle,'display_name',p.display_name) order by f.created_at desc),'[]'::jsonb)
 into v_in from public.jiuli_social_friends f
 join public.jiuli_web_profiles p on p.user_id=f.requested_by
 where f.status='pending' and f.requested_by<>v_uid and (f.user_a=v_uid or f.user_b=v_uid);
 select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('user_id',p.user_id,'handle',p.handle,'display_name',p.display_name) order by f.created_at desc),'[]'::jsonb)
 into v_out from public.jiuli_social_friends f
 join public.jiuli_web_profiles p on p.user_id=(case when f.user_a=v_uid then f.user_b else f.user_a end)
 where f.status='pending' and f.requested_by=v_uid;
 select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',i.id,'team_id',i.team_id,'from_handle',p.handle,'from_name',p.display_name,'expires_at',i.expires_at) order by i.created_at desc),'[]'::jsonb)
 into v_invites from public.jiuli_social_team_invites i
 join public.jiuli_secure_teams t on t.id=i.team_id and t.status='open'
 join public.jiuli_web_profiles p on p.user_id=i.sender_id
 where i.target_id=v_uid and i.status='pending' and i.expires_at>pg_catalog.now();
 select pg_catalog.jsonb_build_object('leader',t.leader_id=v_uid,'count',pg_catalog.count(m.user_id)) into v_team
 from public.jiuli_secure_teams t join public.jiuli_secure_team_members m on m.team_id=t.id
 where t.status='open' and t.id=(select m2.team_id from public.jiuli_secure_team_members m2
  join public.jiuli_secure_teams t2 on t2.id=m2.team_id and t2.status='open'
  where m2.user_id=v_uid order by t2.created_at desc limit 1)
 group by t.id,t.leader_id;
 if v_name~'^[a-z0-9_]{3,16}$' then
  select pg_catalog.jsonb_build_object('user_id',p.user_id,'handle',p.handle,'display_name',p.display_name,
   'is_friend',exists(select 1 from public.jiuli_social_friends f where f.status='accepted'
   and f.user_a=least(v_uid,p.user_id) and f.user_b=greatest(v_uid,p.user_id)))
   into v_match from public.jiuli_web_profiles p where pg_catalog.lower(p.handle)=v_name and p.user_id<>v_uid;
 end if;
 select coalesce(pg_catalog.jsonb_agg(q.obj order by q.event_time desc),'[]'::jsonb) into v_recent from (
  select pg_catalog.jsonb_build_object('from',p.handle,'kind',g.kind,'item',g.item_name,'quantity',g.quantity,'at',g.created_at) obj,g.created_at event_time
  from public.jiuli_social_gift_log g join public.jiuli_web_profiles p on p.user_id=g.sender_id
  where g.recipient_id=v_uid order by g.created_at desc limit 10
 ) q;
 return pg_catalog.jsonb_build_object('friends',v_friends,'incoming',v_in,'outgoing',v_out,
  'team_invites',v_invites,'team',v_team,'search',v_match,'gifts_received',v_recent);
end;
$social_view$;

create or replace function public.jiuli_social_action(
 p_action text,p_target text default '',p_kind text default '',p_name text default '',
 p_quantity integer default 1,p_request_id uuid default null)
returns jsonb language plpgsql security definer set search_path='' as $social$
declare
 v_uid uuid:=auth.uid();v_target uuid;v_handle text;v_pair_a uuid;v_pair_b uuid;
 v_rel public.jiuli_social_friends%rowtype;v_state jsonb;v_other jsonb;v_msg text;
 v_qty integer:=coalesce(p_quantity,0);v_kind text:=coalesce(p_kind,'');v_name text:=pg_catalog.left(coalesce(p_name,''),80);
 v_existing jsonb;v_team uuid;v_inv uuid;v_old_gold bigint;v_old_y bigint;v_other_gold bigint;v_other_y bigint;
 v_items jsonb;v_fish jsonb;v_captured jsonb;v_counter integer:=0;v_active bigint;
begin
 if v_uid is null then raise exception 'LOGIN_REQUIRED';end if;
 if p_request_id is null then p_request_id:=gen_random_uuid();end if;
 if p_action not in('request','accept','decline','remove','gift','interact','inviteTeam','acceptTeam','declineTeam') then raise exception 'INVALID_SOCIAL_ACTION';end if;
 -- 與正式遊戲的銀行/料理等採同一把交易鎖，防止跨帳號競態。
 perform pg_catalog.pg_advisory_xact_lock(2026,1118);
 select result into v_existing from public.jiuli_social_requests where user_id=v_uid and request_id=p_request_id;
 if found then return v_existing;end if;
 if p_action in('acceptTeam','declineTeam') then
  if p_target !~ '^[0-9a-fA-F-]{36}$' then raise exception 'INVALID_INVITE';end if;
  v_inv:=p_target::uuid;
  select team_id,sender_id into v_team,v_target from public.jiuli_social_team_invites
    where id=v_inv and target_id=v_uid and status='pending' and expires_at>now() for update;
  if v_team is null then raise exception 'INVITE_EXPIRED';end if;
 else
  v_handle:=pg_catalog.lower(pg_catalog.btrim(pg_catalog.ltrim(coalesce(p_target,''),'@')));
  if v_handle !~ '^[a-z0-9_]{3,16}$' then raise exception 'INVALID_HANDLE';end if;
  select user_id into v_target from public.jiuli_web_profiles where pg_catalog.lower(handle)=v_handle;
  if v_target is null then raise exception 'PLAYER_NOT_FOUND';end if;
 end if;
 if v_target=v_uid then raise exception 'CANNOT_FRIEND_SELF';end if;
 v_pair_a:=least(v_uid,v_target);v_pair_b:=greatest(v_uid,v_target);
 select * into v_rel from public.jiuli_social_friends
  where user_a=v_pair_a and user_b=v_pair_b for update;
 if p_action='request' then
  if v_rel.status='accepted' then raise exception 'ALREADY_FRIENDS';end if;
  if v_rel.status='blocked' then raise exception 'UNAVAILABLE';end if;
  if v_rel.status='pending' then raise exception 'REQUEST_PENDING';end if;
  if v_rel.status='declined' and v_rel.updated_at>now()-interval '24 hours' then raise exception 'REQUEST_COOLDOWN';end if;
  if (select count(*) from public.jiuli_social_friends where status='accepted' and (user_a=v_uid or user_b=v_uid))>=150
   then raise exception 'FRIEND_LIMIT';end if;
  if (select count(*) from public.jiuli_social_friends where status='pending' and requested_by=v_uid)>=25
   then raise exception 'TOO_MANY_REQUESTS';end if;
  insert into public.jiuli_social_friends(user_a,user_b,requested_by,status)
   values(v_pair_a,v_pair_b,v_uid,'pending')
   on conflict(user_a,user_b) do update set requested_by=v_uid,status='pending',updated_at=now();
  v_msg:='🤝 已送出好友申請，對方登入後可直接接受';
 elsif p_action='accept' then
  if v_rel.status is distinct from 'pending' or v_rel.requested_by=v_uid then raise exception 'NO_INCOMING_REQUEST';end if;
  if (select count(*) from public.jiuli_social_friends where status='accepted' and (user_a=v_uid or user_b=v_uid))>=150
   then raise exception 'FRIEND_LIMIT';end if;
  update public.jiuli_social_friends set status='accepted',updated_at=now()
  where user_a=v_pair_a and user_b=v_pair_b;
  v_msg:='🎉 已成為好友，現在可以直接贈禮和邀請組隊';
 elsif p_action='decline' then
  if v_rel.status is distinct from 'pending' or v_rel.requested_by=v_uid then raise exception 'NO_INCOMING_REQUEST';end if;
  update public.jiuli_social_friends set status='declined',updated_at=now()
  where user_a=v_pair_a and user_b=v_pair_b;
  v_msg:='已婉拒好友申請';
 elsif p_action='remove' then
  if v_rel.status is distinct from 'accepted' then raise exception 'NOT_FRIENDS';end if;
  delete from public.jiuli_social_friends where user_a=v_pair_a and user_b=v_pair_b;
  v_msg:='已解除好友關係';
 else
  if v_rel.status is distinct from 'accepted' then raise exception 'NOT_FRIENDS';end if;
  if p_action in ('gift','interact') then
   select state into v_state from public.jiuli_secure_accounts where user_id=v_uid for update;
   select state into v_other from public.jiuli_secure_accounts where user_id=v_target for update;
   if v_state is null or v_other is null then raise exception 'PLAYER_SAVE_REQUIRED';end if;
   v_old_gold:=public.jiuli_secure_int(v_state,'gold');v_old_y:=public.jiuli_secure_int(v_state,'yuanbao');
   v_other_gold:=public.jiuli_secure_int(v_other,'gold');v_other_y:=public.jiuli_secure_int(v_other,'yuanbao');
  end if;
  if p_action='gift' then
   if v_qty<1 or v_qty>10000000 then raise exception 'INVALID_QUANTITY';end if;
   if (select count(*) from public.jiuli_social_gift_log where sender_id=v_uid and created_at>now()-interval '24 hours')>=30
   then raise exception 'GIFT_DAILY_LIMIT';end if;
   if v_kind in('gold','yuanbao') then
    if v_qty>1000000 then raise exception 'GIFT_TOO_LARGE';end if;
    if public.jiuli_secure_int(v_state,v_kind)<v_qty then raise exception 'NOT_ENOUGH_CURRENCY';end if;
    v_state:=public.jiuli_secure_set(v_state,v_kind,public.jiuli_secure_int(v_state,v_kind)-v_qty);
    if public.jiuli_secure_int(v_other,v_kind)+v_qty>900000000000000 then raise exception 'CURRENCY_LIMIT';end if;
    v_other:=public.jiuli_secure_set(v_other,v_kind,public.jiuli_secure_int(v_other,v_kind)+v_qty);
    v_name:=case when v_kind='gold' then '金幣' else '元寶' end;
   elsif v_kind in('item','chest') then
    if v_qty>100 or v_name='' then raise exception 'INVALID_QUANTITY';end if;
    if public.jiuli_secure_int(v_state->(case when v_kind='item' then 'items' else 'chests' end),v_name)<v_qty then raise exception 'ITEM_NOT_OWNED';end if;
    v_state:=public.jiuli_secure_adjust(v_state,case when v_kind='item' then 'items' else 'chests' end,v_name,-v_qty);
    v_other:=public.jiuli_secure_adjust(v_other,case when v_kind='item' then 'items' else 'chests' end,v_name,v_qty);
   elsif v_kind in('fragments','fruit') then
    if v_qty>100 then raise exception 'INVALID_QUANTITY';end if;
    if public.jiuli_secure_int(v_state,v_kind)<v_qty then raise exception 'ITEM_NOT_OWNED';end if;
    v_state:=public.jiuli_secure_set(v_state,v_kind,public.jiuli_secure_int(v_state,v_kind)-v_qty);
    if public.jiuli_secure_int(v_other,v_kind)+v_qty>900000000000000 then raise exception 'CURRENCY_LIMIT';end if;
    v_other:=public.jiuli_secure_set(v_other,v_kind,public.jiuli_secure_int(v_other,v_kind)+v_qty);
    v_name:=case when v_kind='fragments' then '寵物碎片' else '戰力果實' end;
   elsif v_kind='fish' then
    if v_qty>10 or v_name='' then raise exception 'INVALID_QUANTITY';end if;
    v_fish:='[]'::jsonb;v_captured:='[]'::jsonb;v_counter:=0;
    for v_items in select value from pg_catalog.jsonb_array_elements(coalesce(v_state->'fish','[]'::jsonb)) loop
     if v_items->>'name'=v_name and v_counter<v_qty then
      v_captured:=v_captured||pg_catalog.jsonb_build_array(v_items);v_counter:=v_counter+1;
     else v_fish:=v_fish||pg_catalog.jsonb_build_array(v_items);end if;
    end loop;
    if v_counter<v_qty then raise exception 'FISH_NOT_OWNED';end if;
    if pg_catalog.jsonb_array_length(coalesce(v_other->'fish','[]'::jsonb))+v_qty>10000 then raise exception 'FISH_POND_FULL';end if;
    v_state:=pg_catalog.jsonb_set(v_state,'{fish}',v_fish,true);
    v_other:=pg_catalog.jsonb_set(v_other,'{fish}',coalesce(v_other->'fish','[]'::jsonb)||v_captured,true);
   else raise exception 'INVALID_GIFT_KIND';end if;
   v_state:=public.jiuli_secure_set(v_state,'generosity',public.jiuli_secure_int(v_state,'generosity')+1);
   v_other:=public.jiuli_secure_set(v_other,'charisma',public.jiuli_secure_int(v_other,'charisma')+1);
   update public.jiuli_secure_accounts set state=v_state,revision=revision+1,updated_at=now() where user_id=v_uid;
   update public.jiuli_secure_accounts set state=v_other,revision=revision+1,updated_at=now() where user_id=v_target;
   insert into public.jiuli_social_gift_log(sender_id,recipient_id,kind,item_name,quantity)
     values(v_uid,v_target,v_kind,v_name,v_qty);
   insert into public.jiuli_secure_events(user_id,action,note,before_gold,after_gold,before_yuanbao,after_yuanbao)
     values(v_uid,'friendGift',v_name||'×'||v_qty,v_old_gold,public.jiuli_secure_int(v_state,'gold'),v_old_y,public.jiuli_secure_int(v_state,'yuanbao'));
   insert into public.jiuli_secure_events(user_id,action,note,before_gold,after_gold,before_yuanbao,after_yuanbao)
     values(v_target,'friendGiftReceive',v_name||'×'||v_qty,v_other_gold,public.jiuli_secure_int(v_other,'gold'),v_other_y,public.jiuli_secure_int(v_other,'yuanbao'));
   v_msg:='🎁 贈送'||v_name||'×'||v_qty||'成功，豪氣值+1；好友魅力值+1';
  elsif p_action='interact' then
   if v_name not in ('打招呼','送抱抱','一起加油','幫好友比讚','互相鼓勵') then raise exception 'INVALID_INTERACTION';end if;
   if (select count(*) from public.jiuli_social_interactions where sender_id=v_uid and recipient_id=v_target
      and created_at>now()-interval '1 day')>=5 then raise exception 'INTERACT_DAILY_LIMIT';end if;
   if (select count(*) from public.jiuli_social_interactions where sender_id=v_uid
      and created_at>now()-interval '1 day')>=30 then raise exception 'INTERACT_GLOBAL_LIMIT';end if;
   if exists(select 1 from public.jiuli_social_interactions where sender_id=v_uid and recipient_id=v_target
      and created_at>now()-interval '10 minutes') then raise exception 'INTERACT_COOLDOWN';end if;
   v_state:=public.jiuli_secure_set(v_state,'generosity',public.jiuli_secure_int(v_state,'generosity')+1);
   v_other:=public.jiuli_secure_set(v_other,'charisma',public.jiuli_secure_int(v_other,'charisma')+1);
   update public.jiuli_secure_accounts set state=v_state,revision=revision+1,updated_at=now() where user_id=v_uid;
   update public.jiuli_secure_accounts set state=v_other,revision=revision+1,updated_at=now() where user_id=v_target;
   insert into public.jiuli_social_interactions(sender_id,recipient_id,kind) values(v_uid,v_target,v_name);
   v_msg:='💌 和好友'||v_name||'成功，雙方社交值提升';
  elsif p_action='inviteTeam' then
   select id into v_team from public.jiuli_secure_teams
    where leader_id=v_uid and status='open' order by created_at desc limit 1 for update;
   if v_team is null then
    if exists(select 1 from public.jiuli_secure_team_members m join public.jiuli_secure_teams t on t.id=m.team_id
      where m.user_id=v_uid and t.status='open') then raise exception 'NOT_TEAM_LEADER';end if;
    insert into public.jiuli_secure_teams(code,leader_id)
     values(pg_catalog.upper(pg_catalog.substr(pg_catalog.replace(gen_random_uuid()::text,'-',''),1,8)),v_uid) returning id into v_team;
    insert into public.jiuli_secure_team_members(team_id,user_id) values(v_team,v_uid);
   end if;
   if exists(select 1 from public.jiuli_secure_team_members where team_id=v_team and user_id=v_target)
      then raise exception 'ALREADY_IN_TEAM';end if;
   if (select count(*) from public.jiuli_secure_team_members where team_id=v_team)>=5 then raise exception 'TEAM_FULL';end if;
   if exists(select 1 from public.jiuli_social_team_invites where team_id=v_team and target_id=v_target
      and status='pending' and created_at>now()-interval '10 minutes') then raise exception 'INVITE_COOLDOWN';end if;
   if (select count(*) from public.jiuli_social_team_invites where team_id=v_team and status='pending' and expires_at>now())>=10 then raise exception 'TOO_MANY_INVITES';end if;
   insert into public.jiuli_social_team_invites(team_id,sender_id,target_id,status,expires_at)
     values(v_team,v_uid,v_target,'pending',now()+interval '48 hours')
     on conflict(team_id,target_id) do update set status='pending',created_at=now(),expires_at=now()+interval '48 hours';
   v_msg:='⚔️ 已向好友發出組隊邀請；對方在好友頁面按接受即可';
  elsif p_action='acceptTeam' then
   if exists(select 1 from public.jiuli_secure_team_members m join public.jiuli_secure_teams t on t.id=m.team_id
     where m.user_id=v_uid and t.status='open') then raise exception 'ALREADY_IN_TEAM';end if;
   if not exists(select 1 from public.jiuli_secure_teams where id=v_team and status='open') then raise exception 'TEAM_NOT_FOUND';end if;
   if (select count(*) from public.jiuli_secure_team_members where team_id=v_team)>=5 then raise exception 'TEAM_FULL';end if;
   insert into public.jiuli_secure_team_members(team_id,user_id) values(v_team,v_uid);
   update public.jiuli_social_team_invites set status='accepted' where id=v_inv;
   v_msg:='⚔️ 已接受好友組隊邀請；隊長現在可以直接發起副本';
  elsif p_action='declineTeam' then
   update public.jiuli_social_team_invites set status='declined' where id=v_inv;
   v_msg:='已婉拒組隊邀請';
  end if;
 end if;
 v_existing:=pg_catalog.jsonb_build_object('message',v_msg,'ok',true);
 insert into public.jiuli_social_requests(user_id,request_id,result) values(v_uid,p_request_id,v_existing);
 return v_existing;
end;
$social$;
revoke all on function public.jiuli_social_snapshot(text) from public,anon,authenticated;
revoke all on function public.jiuli_social_action(text,text,text,text,integer,uuid) from public,anon,authenticated;
grant execute on function public.jiuli_social_snapshot(text) to authenticated;
grant execute on function public.jiuli_social_action(text,text,text,text,integer,uuid) to authenticated;
